"""Random byte buffers, weighted towards the values that catch a wrong
initial value, a wrong bit order, or an unguarded top-bit byte."""


def generate(rng, count):
    builders = (_random_bytes, _all_same, _top_bit_heavy)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, data, description=""):
    hexed = " ".join("%02X" % b for b in data)
    stdin = "%d\n%s\n" % (len(data), hexed) if data else "0\n\n"
    return {"name": name, "stdin": stdin, "description": description}


def _random_bytes(rng, index):
    n = rng.randint(0, 40)
    data = [rng.randrange(256) for _ in range(n)]
    return _case("a random %d-byte buffer #%d" % (n, index), data)


def _all_same(rng, index):
    n = rng.randint(1, 20)
    value = rng.randrange(256)
    data = [value] * n
    return _case("%d repeats of byte 0x%02X #%d" % (n, value, index), data)


def _top_bit_heavy(rng, index):
    n = rng.randint(1, 16)
    data = [rng.randrange(128, 256) for _ in range(n)]
    return _case("a %d-byte buffer with every top bit set #%d" % (n, index),
                 data,
                 "Every byte is >= 0x80 -- the promotion-to-int case.")
